// Block (Frame posture, block-contract.md §1b) — a full-height side panel: a head naming the panel,
// with an optional close, over a body that takes the rest of the panel's height.
//
// It exists because the theme studio and the screen composer built it by hand five times (a Card,
// a CardTitle beside a ghost close Button, a CardDescription, a ScrollArea), and the five copies had
// already drifted apart on the gap under the head. The content region is an open `children` slot,
// so this is chrome only, as the Frame posture asks.
//
// Named `SidePanel`, not `Panel`: "Panel" is block-contract.md §1b's name for a posture.
//
// The surface is a flat `Card` at its default tier: it sits in the shell's flow rather than floating
// (prop-usage-contract.md § Variant, surface), and a panel that runs a sidebar's height is not the
// compact chrome `small` is for.
//
// The body does not scroll by itself. A slot wrapper does not own scrolling for content it does not
// render (component-contract.md §6, rule 4's note on scrollports): a panel that scrolls everything
// passes one `ScrollArea`, and one that keeps a search field fixed above a list scrolls the list
// alone. The body fills the height left under the head, so a child given `flex: 1` takes it.
import { useId } from "react";
import type { CSSProperties, ReactNode, Ref } from "react";
import { SidebarLeft2 } from "../components/icons";
import { Button } from "../components/Button";
import { Card, CardDescription, CardTitle } from "../components/Card";
import { Tooltip } from "../components/Tooltip";
import { Stack } from "../layouts/Stack";
import "./SidePanel.css";

export interface SidePanelBaseProps {
  /** The panel's name: its heading, and the accessible name of the region. */
  title: string;
  /**
   * Heading level of the title, so the panel sits at the right depth in the page outline.
   *
   * @default 2
   */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
  /** A supporting line under the title: what the panel is for. */
  description?: ReactNode;
}

export type SidePanelProps = SidePanelBaseProps &
  (
    | {
        /** Called when the head's close Button is pressed. Omit it and the head draws no close. */
        onClose: () => void;
        /**
         * The close Button's accessible name, and its Tooltip. REQUIRED with `onClose`: the Button
         * is icon-only, so this is the only name it has (component-contract.md §2, WCAG 4.1.2).
         */
        closeLabel: string;
      }
    | { onClose?: undefined; closeLabel?: undefined }
  ) & {
    /**
     * The panel's body, a column at `large` under the head. It fills the rest of the panel's height
     * and does not scroll by itself: wrap what should scroll in a `ScrollArea` and give it `flex: 1`.
     */
    children: ReactNode;
    /** Additional class (optional). sd-sidepanel is always preserved. */
    className?: string;
    /** Inline style passthrough, onto the Card. */
    style?: CSSProperties;
    /** Forwarded to the root Card. */
    ref?: Ref<HTMLDivElement>;
  };

export function SidePanel({
  title,
  headingLevel = 2,
  description,
  onClose,
  closeLabel,
  children,
  className,
  style,
  ref,
}: SidePanelProps) {
  const titleId = useId();
  return (
    <Card
      ref={ref}
      role="region"
      aria-labelledby={titleId}
      style={style}
      className={className ? `sd-sidepanel ${className}` : "sd-sidepanel"}
    >
      {/* spacing: `large` under the head. heading-group (token-contract.md § By relationship): the
          head is ATTACHED to the body it names, so its gap floors at the loosest gap inside the
          body, which the studio's bodies keep at `large` and under (ControlGroup's controls, the
          composer's lists); the Card's padding is an edge and seals the unit, so no gap outside it
          bounds this one from above. Two of the five hand-built copies used `x-large`, which reads
          the head as parted from its own body. */}
      <Stack direction="column" gap="large" className="sd-sidepanel__layout">
        <Stack direction="column" gap="2x-small">
          <Stack direction="row" align="center" justify="between" gap="small">
            <CardTitle id={titleId} headingLevel={headingLevel}>
              {title}
            </CardTitle>
            {onClose && (
              <Tooltip content={closeLabel}>
                <Button variant="ghost" isIconOnly aria-label={closeLabel} onPress={onClose}>
                  <SidebarLeft2 aria-hidden size="1em" />
                </Button>
              </Tooltip>
            )}
          </Stack>
          {description != null && <CardDescription>{description}</CardDescription>}
        </Stack>
        <Stack direction="column" gap="large" className="sd-sidepanel__body">
          {children}
        </Stack>
      </Stack>
    </Card>
  );
}

/* SidePanel.css — arrangement only (Block carve-out, component-contract.md §6 carve-out 5).

   The surface, padding and radius are the Card's; the gaps are the Stacks'. What is left is the
   height chain: the panel takes its container's whole height and the body takes what the head
   leaves, so a scroller inside it can fill and scroll. */

/* The Card fills its container's block axis, and `min-block-size: 0` lets a flex parent shrink it
   below its content, so a scroller in the body scrolls instead of the page. The body sits INSIDE
   the Card's padding (the arrangement `Dialog.css` uses), so a child painting past its own box is
   not cut by the Card's edge. The Card is already a flex column, so its one child fills it with
   `flex: 1`. */
.sd-sidepanel {
  block-size: 100%;
  min-block-size: 0;
  min-inline-size: 0;
}

.sd-sidepanel__layout {
  flex: 1;
  min-block-size: 0;
  min-inline-size: 0;
}

.sd-sidepanel__body {
  flex: 1;
  min-block-size: 0;
  min-inline-size: 0;
}
